#!/usr/bin/env bash
set -euo pipefail
[[ $EUID -eq 0 ]] || { echo 'Run with sudo'; exit 1; }
[[ $# -eq 3 ]] || { echo 'Usage: sudo bash scripts/restore.sh BACKUP.tar.age AGE_IDENTITY_FILE RESTORE'; exit 1; }
[[ "$3" == RESTORE ]] || exit 1
archive="$1"; identity="$2"
[[ -f "$archive" && -f "$identity" ]] || exit 1
umask 077
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
age -d -i "$identity" -o "$work/archive.tar" "$archive"
# Only extract known members from backups generated by backup.sh.
if tar -tf "$work/archive.tar" | awk '/(^\/|(^|\/)\.\.(\/|$))/ { found=1 } END { exit !found }'; then echo 'Unsafe archive path'; exit 1; fi
tar -xf "$work/archive.tar" -C "$work" database.dump uploads environment.env package-lock.json
cd /opt/febro-one
[[ -f .env ]] || { echo 'Configure target .env first'; exit 1; }
echo 'This restores ONLY database febro_one and /var/lib/febro-one/uploads. Take a fresh backup first.'
read -r -p 'Type febro_one to confirm replacement: ' confirmation
[[ "$confirmation" == febro_one ]] || exit 1
systemctl stop febro-one
# Existing target credentials are retained; archived environment is for reference only.
cat "$work/database.dump" | sudo -u postgres pg_restore --clean --if-exists --no-owner --role=febro_one --dbname=febro_one --exit-on-error
# Keep the previous uploads directory for rollback rather than deleting it.
if [[ -d /var/lib/febro-one/uploads ]]; then mv /var/lib/febro-one/uploads "/var/lib/febro-one/uploads-before-restore-$(date +%s)"; fi
install -d -m 700 -o febro-one -g febro-one /var/lib/febro-one/uploads
cp -a "$work/uploads/." /var/lib/febro-one/uploads/
chown -R febro-one:febro-one /var/lib/febro-one/uploads
systemctl start febro-one
curl --fail http://127.0.0.1:3470/api/health
